CREATE DATABASE IF NOT EXISTS employee_management;
USE employee_management;

DROP TABLE IF EXISTS employee_salaries;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS positions;
DROP TABLE IF EXISTS departments;

CREATE TABLE departments (
    department_id INT PRIMARY KEY,
    department_name VARCHAR(100) NOT NULL UNIQUE,
    location VARCHAR(100) NOT NULL
);

CREATE TABLE positions (
    position_id INT PRIMARY KEY,
    position_title VARCHAR(100) NOT NULL UNIQUE,
    employment_level VARCHAR(50) NOT NULL,
    base_salary DECIMAL(12,2) NOT NULL
);

CREATE TABLE employees (
    employee_id INT PRIMARY KEY,
    employee_number VARCHAR(20) NOT NULL UNIQUE,
    first_name VARCHAR(50) NOT NULL,
    middle_name VARCHAR(50),
    last_name VARCHAR(50) NOT NULL,
    gender ENUM('Male','Female') NOT NULL,
    birth_date DATE NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    phone VARCHAR(20),
    hire_date DATE NOT NULL,
    department_id INT NOT NULL,
    position_id INT NOT NULL,
    employment_status ENUM('Active','Inactive','On Leave') NOT NULL DEFAULT 'Active',
    FOREIGN KEY (department_id) REFERENCES departments(department_id),
    FOREIGN KEY (position_id) REFERENCES positions(position_id)
);

CREATE TABLE employee_salaries (
    salary_id INT PRIMARY KEY,
    employee_id INT NOT NULL,
    salary_amount DECIMAL(12,2) NOT NULL,
    salary_type ENUM('Monthly','Daily') NOT NULL DEFAULT 'Monthly',
    effective_date DATE NOT NULL,
    end_date DATE NULL,
    FOREIGN KEY (employee_id) REFERENCES employees(employee_id) ON DELETE CASCADE
);





-- Verification queries:
SELECT COUNT(*) AS employee_rows FROM employees; -- should return 1000
SELECT COUNT(*) AS salary_rows FROM employee_salaries; -- should return 1000
SELECT COUNT(*) AS department_rows FROM departments; -- should return 10
SELECT COUNT(*) AS position_rows FROM positions; -- should return 33